// Ждём появления .quiz-container-4 (если вопрос загружается динамически)
const observer4 = new MutationObserver((mutations, obs) => {
  const question4Container = document.querySelector('.quiz-container-4');

  if (question4Container) {
      obs.disconnect();
      waitForQuestion4();
  }
});

observer4.observe(document.body, { childList: true, subtree: true });

function waitForQuestion4() {
    let attempts = 0;
    const interval = setInterval(() => {
        const checkAnswerButton = document.querySelector('.check-answer-button');
        const feedbackElement = document.querySelector('.feedback');
        const sortableList = document.querySelector('.quiz-container-4__sortable');
        if (checkAnswerButton && feedbackElement && sortableList) {
            clearInterval(interval);
            setTimeout(() => initQuestion4(), 100);
        }

        attempts++;
        if (attempts > 10) {
            console.error('❌ Вопрос 4 не загрузился!');
            clearInterval(interval);
        }
    }, 300);
}


let question4Initialized = false; // Флаг, чтобы initQuestion4() не запускался повторно

function initQuestion4() {
    if (window.question4Initialized) return;
    window.question4Initialized = true;

    const checkAnswerButton = document.querySelector('.check-answer-button');
    const feedbackElement = document.querySelector('.feedback');
    const sortableList = document.querySelector('.quiz-container-4__sortable');

    if (!checkAnswerButton || !feedbackElement || !sortableList) {
        return;
    }

    const questionId = checkAnswerButton.getAttribute('data-question-id');
    const lang = localStorage.getItem('selectedLang') || 'ru';
    enableInputs();
    sortableList.replaceWith(sortableList.cloneNode(true));
    const newSortableList = document.querySelector('.quiz-container-4__sortable');

    setTimeout(() => {
        initCustomDragAndDrop(newSortableList);
    }, 100);

    checkAnswerButton.addEventListener('click', () => {
        const userOrder = Array.from(document.querySelectorAll(".quiz-container-4__item")).map(el => el.innerHTML);

        fetch(`${basePath}/answer_handler.php?get_answer=${questionId}&lang=${lang}`)
            .then((response) => response.json())
            .then((data) => {
                if (!data || data.error) {
                    feedbackElement.innerHTML = translator.t('error-response');
                    feedbackElement.classList.add('active'); // ✅ Добавляем "active" при ошибке
                    console.error('❌ Ошибка сервера:', data.error);
                    return;
                }

                const correctOrder = data.correctOrder;
                const isCorrect = JSON.stringify(userOrder) === JSON.stringify(correctOrder);
                const correctAnswerInfoEl = document.querySelector('.correct-answer-info');
                if (correctAnswerInfoEl) {
                    correctAnswerInfoEl.setAttribute('data-answer', data.correctOrder.join(', '));
                  }

                handleQuizLogic4(isCorrect, checkAnswerButton);
            })
            .catch((error) => {
                console.error('❌ Ошибка связи с сервером:', error);
                feedbackElement.innerHTML = translator.t('error-response');
                feedbackElement.classList.add('active'); // ✅ Добавляем "active" при ошибке связи
            });
    });
  }
function handleQuizLogic4(isCorrect, button) {
    const sortableList = document.querySelector('.quiz-container-4__sortable');
    setFeedbackAndRestartButton(isCorrect, button);
    disableInputs(); // ✅ Отключаем все инпуты
    // 🔥 Отключаем возможность перетаскивания
    disableDragAndDrop(sortableList);
    button.addEventListener(
        'click',
        () => {
            clearQuizUI();
            window.question4Initialized = false;
            observer4.observe(document.body, { childList: true, subtree: true });
        },
        { once: true }
    );
  }



// ✅ Функция для отключения перетаскивания
function disableDragAndDrop(sortableList) {
    if (!sortableList) return;
  const sortableItems = sortableList.querySelectorAll('.quiz-container-4__item');

  sortableItems.forEach(item => {
      item.draggable = false; // 🔥 Отключаем Drag & Drop
      item.style.cursor = "default"; // 🔥 Меняем курсор, чтобы не было "перетаскивания"
  });

  // 🔥 Удаляем обработчики событий для Drag & Drop
  sortableList.replaceWith(sortableList.cloneNode(true));
}


