function initCustomDragAndDrop(sortableList) {
    let draggedItem = null;
    const placeholder = document.createElement("li");
    placeholder.className = "sortable-placeholder";

    const listRect = sortableList.getBoundingClientRect();

    function startDrag(evt) {
        const isTouch = evt.type === "touchstart";
        const clientX = isTouch ? evt.touches[0].clientX : evt.clientX;
        const clientY = isTouch ? evt.touches[0].clientY : evt.clientY;

        // Определяем, какой элемент тащим
        const item = (isTouch ? document.elementFromPoint(clientX, clientY) : evt.target).closest(".quiz-container-4__item");
        if (!item) return;

        if (!isTouch) evt.preventDefault();

        draggedItem = item;
        draggedItem.style.width = `${sortableList.clientWidth}px`;
        draggedItem.style.height = `${draggedItem.offsetHeight}px`;

        item.after(placeholder);

        // Переводим элемент в абсолют и начинаем перемещение
        draggedItem.style.position = "absolute";
        draggedItem.style.zIndex = "1000";
        draggedItem.style.pointerEvents = "none";
        draggedItem.style.left = "0px";
        draggedItem.style.width = "100%";

        moveAt(clientY);

        function moveAt(pageY) {
            const minY = 0;
            const maxY = sortableList.clientHeight - draggedItem.offsetHeight;
            const newY = Math.min(Math.max(pageY - listRect.top, minY), maxY);
            draggedItem.style.top = `${newY}px`;
        }

        function onMove(event) {
            const moveX = isTouch ? event.touches[0].clientX : event.clientX;
            const moveY = isTouch ? event.touches[0].clientY : event.clientY;

            moveAt(moveY);

            const elemBelow = document.elementFromPoint(moveX, moveY);
            const droppableBelow = elemBelow?.closest(".quiz-container-4__item");

            // Перемещаем placeholder по направлению к ближайшему элементу
            if (droppableBelow && droppableBelow !== draggedItem) {
                const centerY = droppableBelow.getBoundingClientRect().top + droppableBelow.offsetHeight / 2;
                if (moveY < centerY) {
                    droppableBelow.before(placeholder);
                } else {
                    droppableBelow.after(placeholder);
                }
            }
        }

        function onEnd() {
            if (isTouch) {
                document.removeEventListener("touchmove", onMove);
                document.removeEventListener("touchend", onEnd);
            } else {
                document.removeEventListener("mousemove", onMove);
                document.removeEventListener("mouseup", onEnd);
            }

            // Завершаем перетаскивание и возвращаем элемент
            placeholder.replaceWith(draggedItem);
            draggedItem.classList.remove("dragging");

            draggedItem.style.position = "";
            draggedItem.style.zIndex = "";
            draggedItem.style.left = "";
            draggedItem.style.top = "";
            draggedItem.style.width = "";
            draggedItem.style.pointerEvents = "";

            draggedItem = null;
        }

        if (isTouch) {
            document.addEventListener("touchmove", onMove, { passive: false });
            document.addEventListener("touchend", onEnd);
        } else {
            document.addEventListener("mousemove", onMove);
            document.addEventListener("mouseup", onEnd);
        }
    }

    // Подключаем drag’n’drop на мышь и тач
    sortableList.addEventListener("mousedown", startDrag);
    sortableList.addEventListener("touchstart", startDrag, { passive: false });
}
