document.addEventListener("DOMContentLoaded", function () {
  const select = document.querySelector(".language-selector");
  const buttons = document.querySelectorAll(".language-screen__btn");

  // Функция: делает активной кнопку соответствующего языка
  function updateActiveButton(lang) {
      buttons.forEach(btn => {
          // Добавляем класс "active" только той кнопке, чей data-lang совпадает
          btn.classList.toggle("active", btn.dataset.lang === lang);
      });
  }

  // Вешаем обработчик клика на каждую кнопку
  buttons.forEach(button => {
      button.addEventListener("click", () => {
          const lang = button.dataset.lang;
          select.value = lang;
          select.dispatchEvent(new Event("change"));
          updateActiveButton(lang);
      });
  });

  // При загрузке: делаем активной кнопку в соответствии с текущим языком в <select>
  updateActiveButton(select.value);
});



document.addEventListener('DOMContentLoaded', () => {
  const header = document.querySelector('.header');
  const headerImage = document.getElementById('question-number-img');

  function updateQuestionImage() {
    const quizContainer = document.querySelector('[class*="quiz-container-"]');

    if (quizContainer) {
      const match = quizContainer.className.match(/quiz-container-(\d+)/);
      if (match) {
        const questionNumber = match[1].padStart(3, '0'); // Преобразуем в 001, 002, 003...
        headerImage.src = `${basePath}/assets/img/${questionNumber}.png`;

        // Добавляем класс header-question
        if (!header.classList.contains('header-question')) {
          header.classList.add('header-question');
        }
      }
    }
  }
  function removeHeaderQuestionClass() {
    const header = document.querySelector('.header');
    if (header.classList.contains('header-question')) {
      header.classList.remove('header-question');
    }
  }

  window.headerLogic = {
    updateQuestionImage,
    removeHeaderQuestionClass
  };
});


// Устанавливаем значение --vh (1% от высоты окна) в переменную CSS
function setFullHeight() {
  document.documentElement.style.setProperty('--vh', `${window.innerHeight * 0.01}px`);
}
setFullHeight();
window.addEventListener('resize', setFullHeight);

// Загружаем переводы по выбранному языку
function loadTranslations(lang = null) {
  if (lang) {
      localStorage.setItem('selectedLang', lang);
  } else {
      lang = localStorage.getItem('selectedLang') || 'ru';
  }

  // Загружаем переводы с сервера
  return fetch(`${basePath}/get_translations.php?lang=${lang}`)
      .then(response => response.json())
      .then(data => {
        window.translations = data;
        updateUIText();
      })
      .catch(error => console.error("❌ Ошибка загрузки переводов:", error));
}



// ✅ Обновляет текст UI на странице
function updateUIText() {
  document.querySelectorAll('[data-translate]').forEach(el => {
    const key = el.getAttribute('data-translate');
    const translated = window.translations?.[key];

    // ✅ Только если перевод есть — подставляем
    if (translated !== undefined && translated !== null) {
      el.innerHTML = translated || '';

    }

  });
}


// ✅ Обновляем переводы при загрузке страницы
document.addEventListener("DOMContentLoaded", async () => {
  await loadTranslations();
  updateUIText();
});


// ✅ Переключение языка
document.addEventListener('DOMContentLoaded', () => {
  const languageScreen = document.querySelector('.language-screen'); // Один экран выбора языка
  const beginScreen = document.querySelector('.begin-screen'); // Один экран "Начать"
  const quizScreen = document.querySelector('.quiz-screen'); // Один экран викторины
  const startButton = document.querySelector('.start-button'); // Одна кнопка "Начать"

  // ✅ Получаем сохранённый язык из localStorage
  let savedLang = localStorage.getItem('selectedLang') || 'ru';

  // ✅ Меняем текст кнопки "Начать" вручную, без translator.t()
  if (startButton) {
    startButton.innerHTML = savedLang === 'ru' ? "Начать" : "Start";
  }

  // ✅ Переключение языка
  document.querySelectorAll('.language-selector, .language-screen__btn').forEach(button => {
    button.addEventListener('click', (event) => {
      let newLang = event.target.getAttribute('data-lang') || event.target.value;
      localStorage.setItem('selectedLang', newLang);

      // ✅ Обновляем кнопку "Начать"
      if (startButton) {
        startButton.innerHTML = newLang === 'ru' ? "Начать" : "Start";
      }

      // ✅ Обновляем весь UI
      loadTranslations(newLang).then(() => {
        updateUIText();
      });
    });
  });

  // ✅ Начать викторину (ОДИН раз!)
  if (startButton) {
    startButton.addEventListener('click', () => {
      // 🔥 Скрываем экран выбора языка и кнопку "Начать"
      if (languageScreen) languageScreen.classList.add('hidden');
      if (beginScreen) beginScreen.classList.add('hidden');

      // 🔥 Показываем викторину с анимацией
      if (quizScreen) {
        quizScreen.classList.remove('hidden');

        setTimeout(() => {
          quizScreen.classList.add('fade-in');
        }, 50);
      }

      // 🔥 Загружаем новый случайный вопрос (ТОЛЬКО ОДИН РАЗ!)
      updateQuestion();
    });
  }
});



// Класс переводчика
class Translator {
  constructor(defaultLang = 'ru') {
    this.lang = localStorage.getItem('selectedLang') || defaultLang;
    this.translations = window.translations || {};
    this.updateUI();
  }

  setLanguage(lang) {
    localStorage.setItem('selectedLang', lang);
    this.lang = lang;
    this.updateUI();
  }

  updateUI() {
    document.querySelectorAll('[data-translate]').forEach((el) => {
      const key = el.getAttribute('data-translate');
      el.innerHTML = this.translations[this.lang]?.[key] || '';
    });

    document.querySelectorAll('.language-selector').forEach((selector) => {
      selector.value = this.lang;
    });
  }

  t(key) {
    return window.translations?.[key] || key;
  }

}

let translator = new Translator();

document.addEventListener('DOMContentLoaded', () => {
  // Переключение языка
  document.querySelectorAll('.language-selector').forEach((selector) => {
    selector.addEventListener('change', (event) => {
      translator.setLanguage(event.target.value);
    });
  });
});

// Глобальная функция загрузки нового вопроса
function updateQuestion() {

  const lang = localStorage.getItem("selectedLang") || "ru";
  const quizScreens = document.querySelectorAll(".quiz-screen");

  const questionTypes = ["1", "2", "3", "4", "5", "6", "7"];

  const questionType = questionTypes[Math.floor(Math.random() * questionTypes.length)];

  fetch(`${basePath}/questions/question_type${questionType}.php?lang=${lang}`)
    .then((response) => response.text())
    .then((html) => {

      quizScreens.forEach((screen) => {
        screen.innerHTML = html;
        headerLogic.updateQuestionImage();
      });
      updateUIText();

      // 🔥 Динамически вызываем нужный `waitForQuestionX()`
      const waitFunction = window[`waitForQuestion${questionType}`];
      if (typeof waitFunction === "function") {
        waitFunction();
      } else {
        console.error(`❌ Ошибка: функция waitForQuestion${questionType} не найдена!`);
      }
    })
    .catch((error) => console.error("❌ Ошибка загрузки вопроса:", error));
}

function normalizeAnswer(text) {
  return text
    .trim()
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-zа-яё\s]/g, '')
    .replace(/\s+/g, ' ')
}

function disableInputs() {
  let attempts = 0;

  const interval = setInterval(() => {
    const inputs = document.querySelectorAll('input');
    if (inputs.length > 0) {
      inputs.forEach((input) => {
        if (input.type === 'radio') {
          if (input.checked) {
            input.setAttribute('data-checked', 'true'); // Запоминаем выбранный radio
          }
          input.disabled = true; // Отключаем radio
        } else {
          input.readOnly = true; // Отключаем text input
        }
      });

      // ✅ Восстанавливаем выбор у radio
      setTimeout(() => {
        inputs.forEach((input) => {
          if (input.type === 'radio' && input.getAttribute('data-checked') === 'true') {
            input.checked = true;
          }
        });
      }, 50);

      clearInterval(interval);
    }
    attempts++;
    if (attempts > 20) {
      clearInterval(interval);
    }
  }, 200);
}


function setFeedbackAndRestartButton(isCorrect, button) {
  const feedbackElement = document.querySelector('.feedback');
  if (!feedbackElement) return;

  // Сообщение о результате
  feedbackElement.innerHTML = isCorrect
    ? translator.t('correct_answer')
    : translator.t('wrong_answer');
  feedbackElement.classList.add('active');


  // ✅ Показываем правильный ответ, если был неверный
  if (!isCorrect) {
    const correctAnswerEl = document.querySelector('.correct-answer-info');
    const correctAnswerText = correctAnswerEl?.getAttribute('data-answer');

    if (correctAnswerEl && correctAnswerText) {
      const capitalizedAnswer =
        correctAnswerText.charAt(0).toUpperCase() + correctAnswerText.slice(1);

      correctAnswerEl.innerHTML = `
        <div class="incorrect-message">
          <span>${translator.t('wrong_answer_title')}</span><br>
          ${translator.t('correct_answer_info')} ${capitalizedAnswer}
        </div>
      `;
      correctAnswerEl.classList.add('show');
    }
  }



  // Кнопка "Назад"
  const boldRefreshIcon = `<svg width="18" height="18" viewBox="0 0 24 24" fill="white" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 4V2L7 6l5 4V6c3.87 0 7 3.13 7 7s-3.13 7-7 7-7-3.13-7-7H2c0 5.52 4.48 10 10 10s10-4.48 10-10S17.52 2 12 2z"/>
  </svg>`;

  button.innerHTML = boldRefreshIcon + ' ' + translator.t('backward');
  button.setAttribute('data-action', 'restartQuiz');
}


// ✅ Очистка интерфейса при возврате на главную
function clearQuizUI() {
  const feedbackElement = document.querySelector('.feedback');
  const quizScreen = document.querySelector('.quiz-screen');
  const beginScreen = document.querySelector('.begin-screen');
  const languageScreen = document.querySelector('.language-screen');

  if (feedbackElement) {
    feedbackElement.innerHTML = '';
    feedbackElement.classList.remove('active');
  }

  if (quizScreen) {
    quizScreen.innerHTML = '';
    quizScreen.classList.add('hidden');
  }

  if (beginScreen) beginScreen.classList.remove('hidden');
  if (languageScreen) languageScreen.classList.remove('hidden');

  headerLogic.removeHeaderQuestionClass();
}

function enableInputs() {
  const inputs = document.querySelectorAll('input');
  inputs.forEach(input => {
    input.disabled = false;
    input.readOnly = false;
  });
}
