// Ждём появления .quiz-container-7 (если вопрос загружается динамически)
const observer7 = new MutationObserver((mutations, obs) => {
  const question7Container = document.querySelector('.quiz-container-7');

  if (question7Container) {
      obs.disconnect(); // Отключаем наблюдение
      waitForQuestion7();
  }
});

observer7.observe(document.body, { childList: true, subtree: true });

function initQuestion7() {
  if (question7Initialized) return; // Если уже запускался, не запускаем второй раз
  question7Initialized = true;

  const checkAnswerButton = document.querySelector('.check-answer-button');
  const feedbackElement = document.querySelector('.feedback');
  const userAnswerInput = document.querySelector('.user-answer');

  if (!checkAnswerButton || !feedbackElement || !userAnswerInput) {
    console.warn('❌ Элементы вопроса 7 не найдены');
    return;
  }

  const questionId = checkAnswerButton.getAttribute('data-question-id');
  const lang = localStorage.getItem('selectedLang') || 'ru';
  enableInputs();

  checkAnswerButton.addEventListener('click', () => {
    // Нормализуем ответ пользователя
    let userAnswer = normalizeAnswer(userAnswerInput.value);
    console.log(userAnswer)

    if (!userAnswer) {
      feedbackElement.innerHTML = translator.t('placeholder_answer');
      feedbackElement.classList.add('active'); // ✅ Добавляем класс "active"
      return;
    }

    fetch(`${basePath}/answer_handler.php?get_answer=${questionId}&lang=${lang}`)
      .then((response) => response.json())
      .then((data) => {
        if (!data || data.error) {
          feedbackElement.innerHTML = translator.t('error-response');
          feedbackElement.classList.add('active'); // ✅ Добавляем класс "active" при ошибке
          return;
        }

        // Нормализуем правильный ответ
        let correctAnswer = normalizeAnswer(data.correctAnswer);
        const correctAnswerInfoEl = document.querySelector('.correct-answer-info');
        if (correctAnswerInfoEl) {
          correctAnswerInfoEl.setAttribute('data-answer', data.correctAnswer);
        }

        let isCorrect;
        if (questionId === 'question77') {
          const acceptedSynonyms = ['россия', 'рф', 'российская федерация'];
          isCorrect = acceptedSynonyms.includes(userAnswer);
        } else {
          isCorrect = userAnswer === correctAnswer;
        }
        handleQuizLogic7(isCorrect, checkAnswerButton);
      })
      .catch((error) => {
        feedbackElement.innerHTML = translator.t('error-response');
        feedbackElement.classList.add('active'); // ✅ Добавляем класс "active" при ошибке связи
      });
  });
}



let question7Initialized = false; // Флаг, чтобы initQuestion7() не запускался повторно

function waitForQuestion7() {
  let attempts = 0;
  const interval = setInterval(() => {
      const checkAnswerButton = document.querySelector('.check-answer-button');
      const feedbackElement = document.querySelector('.feedback');
      const userAnswerInput = document.querySelector('.user-answer');

      if (checkAnswerButton && feedbackElement && userAnswerInput) {
          clearInterval(interval);
          setTimeout(() => initQuestion7(), 100);
      }

      attempts++;
      if (attempts > 10) {
          console.error('❌ Вопрос 7 не загрузился!');
          clearInterval(interval);
      }
  }, 300);
}


function handleQuizLogic7(isCorrect, button) {
    setFeedbackAndRestartButton(isCorrect, button);
    disableInputs(); // ✅ Отключаем все инпуты
  button.addEventListener(
      'click',
      () => {
        clearQuizUI()

          // Сбрасываем флаг, чтобы initQuestion7 мог запуститься заново при новом вопросе
          question7Initialized = false;

          // Добавляем наблюдение заново после возврата в меню
          observer7.observe(document.body, { childList: true, subtree: true });
      },
      { once: true }
  );
}
