// Ждём появления .quiz-container-1
const observer1 = new MutationObserver((mutations, obs) => {
  const question1Container = document.querySelector('.quiz-container-1');

  if (question1Container) {
      obs.disconnect(); // Отключаем наблюдение
      waitForQuestion1();
  }
});

observer1.observe(document.body, { childList: true, subtree: true });

function waitForQuestion1() {
  let attempts = 0;
  const interval = setInterval(() => {
      const checkAnswerButton = document.querySelector('.check-answer-button');
      const feedbackElement = document.querySelector('.feedback');
      const userAnswerInput = document.querySelector('.user-answer');

      if (checkAnswerButton && feedbackElement && userAnswerInput) {
          clearInterval(interval);
          setTimeout(() => initQuestion1(), 100);
      }

      attempts++;
      if (attempts > 10) {
          console.error('❌ Вопрос 1 не загрузился!');
          clearInterval(interval);
      }
  }, 300);
}

let question1Initialized = false; // Флаг, чтобы initQuestion1() не запускался повторно

function initQuestion1() {
  if (question1Initialized) return; // Если уже запускался, не запускаем второй раз
  question1Initialized = true;

  const checkAnswerButton = document.querySelector('.check-answer-button');
  const feedbackElement = document.querySelector('.feedback');
  const userAnswerInput = document.querySelector('.user-answer');

  if (!checkAnswerButton || !feedbackElement || !userAnswerInput) {
      console.warn('❌ Элементы вопроса 1 не найдены');
      return;
  }
  enableInputs()
  const questionId = checkAnswerButton.getAttribute('data-question-id');
  const lang = localStorage.getItem('selectedLang') || 'ru';

  checkAnswerButton.addEventListener('click', () => {
      let userAnswer = userAnswerInput.value.trim().toLowerCase();

      if (!userAnswer) {
          feedbackElement.innerHTML = translator.t('placeholder_answer');
          feedbackElement.classList.add('active'); // ✅ Добавляем класс "active"
          return;
      }

      // ✅ Нормализация ответа (замена "ё" на "е")
      userAnswer = userAnswer.replace(/ё/g, "е");

      fetch(`${basePath}/answer_handler.php?get_answer=${questionId}&lang=${lang}`)
          .then((response) => response.json())
          .then((data) => {
              if (!data || data.error) {
                  feedbackElement.innerHTML = translator.t('error-response');
                  feedbackElement.classList.add('active'); // ✅ Добавляем класс "active" при ошибке
                  return;
              }
              const correctAnswerInfoEl = document.querySelector('.correct-answer-info');
              if (correctAnswerInfoEl) {
                correctAnswerInfoEl.setAttribute('data-answer', data.correctAnswer);
              }
              let correctAnswer = data.correctAnswer.toLowerCase().replace(/ё/g, "е");
              const isCorrect = userAnswer === correctAnswer;
              handleQuizLogic1(isCorrect, checkAnswerButton);
          })
          .catch((error) => {
              feedbackElement.innerHTML = translator.t('error-response');
              feedbackElement.classList.add('active'); // ✅ Добавляем класс "active" при ошибке связи
          });
  });
}

function handleQuizLogic1(isCorrect, button) {
    setFeedbackAndRestartButton(isCorrect, button);
  button.addEventListener(
      'click',
      () => {
        clearQuizUI()
        disableInputs();
          // Сбрасываем флаг, чтобы initQuestion1 мог запуститься заново при новом вопросе
          question1Initialized = false;

          // Добавляем наблюдение заново после возврата в меню
          observer1.observe(document.body, { childList: true, subtree: true });
      },
      { once: true }
  );
}
