// 🔍 Ждём появления .quiz-container-6 (если вопрос загружается динамически)
const observer6 = new MutationObserver((mutations, obs) => {
  const question6Container = document.querySelector('.quiz-container-6');

  if (question6Container) {
      obs.disconnect(); // Отключаем наблюдение
      waitForQuestion6();
  }
});

observer6.observe(document.body, { childList: true, subtree: true });

function waitForQuestion6() {
  let attempts = 0;
  const interval = setInterval(() => {
      const checkAnswerButton = document.querySelector('.check-answer-button');
      const feedbackElement = document.querySelector('.feedback');

      if (checkAnswerButton && feedbackElement) {
          clearInterval(interval);
          setTimeout(() => initQuestion6(), 100);
      }

      attempts++;
      if (attempts > 10) {
          console.error('❌ Вопрос 6 не загрузился!');
          clearInterval(interval);
      }
  }, 300);
}

let question6Initialized = false; // Флаг, чтобы initQuestion6() не запускался повторно

function initQuestion6() {
  if (question6Initialized) return;
  question6Initialized = true;

  const checkAnswerButton = document.querySelector('.check-answer-button');
  const feedbackElement = document.querySelector('.feedback');

  if (!checkAnswerButton || !feedbackElement) {
      console.warn('❌ Элементы вопроса 6 не найдены');
      return;
  }

  const questionId = checkAnswerButton.getAttribute('data-question-id');
  const lang = localStorage.getItem('selectedLang') || 'ru';
  enableInputs();
  checkAnswerButton.addEventListener('click', () => {
      const selectedOption = document.querySelector('input[name="question6"]:checked');

      if (!selectedOption) {
          if (feedbackElement) {
              feedbackElement.innerHTML = translator.t('answer-choice');
              feedbackElement.classList.add('active'); // ✅ Добавляем "active" при пустом ответе
          }
          return;
      }

      fetch(`${basePath}/answer_handler.php?get_answer=${questionId}&lang=${lang}`)
          .then((response) => response.json())
          .then((data) => {
              if (!data || data.error) {
                  if (feedbackElement) {
                      feedbackElement.innerHTML = translator.t('error-response');
                      feedbackElement.classList.add('active'); // ✅ Добавляем "active" при ошибке
                  }
                  console.error('❌ Ошибка сервера:', data.error);
                  return;
              }

              const correctAnswer = data.correctAnswer;
              const userAnswer = selectedOption.value;
              const isCorrect = userAnswer === correctAnswer;
              const correctAnswerInfoEl = document.querySelector('.correct-answer-info');
              if (correctAnswerInfoEl) {
                correctAnswerInfoEl.setAttribute('data-answer', data.correctAnswer);
              }
              handleQuizLogic6(isCorrect, checkAnswerButton);
          })
          .catch((error) => {
              console.error('❌ Ошибка связи с сервером:', error);
              if (feedbackElement) {
                  feedbackElement.innerHTML = translator.t('error-response');
                  feedbackElement.classList.add('active'); // ✅ Добавляем "active" при ошибке связи
              }
          });
  });

  // === Обновлённая обработка смены класса ===
  const form = document.querySelector(".question6-form");

  if (!form) return;

  form.addEventListener("change", function (event) {
      if (event.target.matches('input[type="radio"]')) {
          // Убираем активный класс у всех label
          form.querySelectorAll("label").forEach(label => label.classList.remove("selected"));

          // Получаем родительский label, так как input внутри него
          const selectedLabel = event.target.closest("label");
          if (selectedLabel) {
              selectedLabel.classList.add("selected"); // ✅ Добавляем "selected" для активного radio
          }
      }
  });
}


function handleQuizLogic6(isCorrect, button) {
    setFeedbackAndRestartButton(isCorrect, button);
    disableInputs(); // ✅ Отключаем все инпуты
  button.addEventListener(
      'click',
      () => {
        clearQuizUI()

          // Сбрасываем флаг, чтобы initQuestion6 мог запуститься заново при новом вопросе
          question6Initialized = false;

          // Добавляем наблюдение заново после возврата в меню
          observer6.observe(document.body, { childList: true, subtree: true });
      },
      { once: true }
  );
}
