// 🔍 Ждём появления .quiz-container-5 (если вопрос загружается динамически)
const observer5 = new MutationObserver((mutations, obs) => {
  const question5Container = document.querySelector('.quiz-container-5');

  if (question5Container) {
    obs.disconnect(); // Отключаем наблюдение
    waitForQuestion5();
  }
});

observer5.observe(document.body, { childList: true, subtree: true });

function waitForQuestion5() {
  let attempts = 0;
  const interval = setInterval(() => {
    const revealButton = document.querySelector(".reveal-letter-button");
    const checkAnswerButton = document.querySelector(".check-answer-button");
    const feedbackElement = document.querySelector(".feedback");
    const letterInputs = document.querySelectorAll(".letter-input");

    if (revealButton && checkAnswerButton && feedbackElement && letterInputs.length) {
      clearInterval(interval);
      setTimeout(() => initQuestion5(), 100);
    }

    attempts++;
    if (attempts > 10) {
      console.error('❌ Вопрос 5 не загрузился!');
      clearInterval(interval);
    }
  }, 300);
}

// ✅ Флаг, чтобы не запускать повторно
let question5Initialized = false;
let openedIndexes = new Set(); // 🔥 Запоминаем открытые буквы

function initQuestion5() {
  if (question5Initialized) return;
  question5Initialized = true;

  const checkAnswerButton = document.querySelector(".check-answer-button");
  const feedbackElement = document.querySelector(".feedback");
  const revealButton = document.querySelector(".reveal-letter-button");
  const questionId = checkAnswerButton.getAttribute("data-question-id");
  const lang = localStorage.getItem("selectedLang") || "ru";
  const inputs = document.querySelectorAll(".letter-input");

  if (!revealButton || !checkAnswerButton || !inputs.length || !feedbackElement) {
    return;
  }

  let remainingHints = 2;
  let selectedInputIndex = null;
  enableInputs();
  inputs.forEach(input => {
    input.readOnly = false;
    input.value = "";
    input.classList.remove("selected");

    input.addEventListener("click", () => {
      if (input.readOnly) return;
      selectedInputIndex = parseInt(input.getAttribute("data-index"));
      inputs.forEach(inp => inp.classList.remove("selected"));
      input.classList.add("selected");
    });

    input.addEventListener("input", (event) => {
      input.value = input.value;

      let nextInput = input.nextElementSibling;
      if (nextInput && !nextInput.readOnly) {
        nextInput.focus();
      }
    });
  });

  // ✅ Открываем букву по клику
  revealButton.addEventListener("click", () => {
    if (remainingHints <= 0 || selectedInputIndex === null) return;

    fetch(`${basePath}/answer_handler.php?get_letter=${selectedInputIndex}&question_id=${questionId}&lang=${lang}`)
      .then(response => response.json())
      .then(data => {
        if (data.error) {
          return;
        }

        inputs[selectedInputIndex].value = data.letter;
        inputs[selectedInputIndex].classList.remove("selected");
        inputs[selectedInputIndex].readOnly = true;

        openedIndexes.add(selectedInputIndex);
        selectedInputIndex = null;

        remainingHints--;
        if (remainingHints === 0) {
          revealButton.classList.add("disabled-button");
        }
      })
      .catch(error => console.error("❌ Ошибка связи с сервером:", error));
  });

  // ✅ Проверяем правильность ответа
  checkAnswerButton.addEventListener("click", () => {
    let userAnswer = "";
    let allFilled = true;

    inputs.forEach((input) => {
      if (!input.value) {
        allFilled = false;
      }
      userAnswer += input.value;
    });

    if (!allFilled) {
      feedbackElement.innerHTML = translator.t("fill_all_letters");
      feedbackElement.classList.add("active"); // ✅ Добавляем "active" при пустом ответе
      return;
    }

    fetch(`/answer_handler.php?get_answer=${questionId}&lang=${lang}`)
      .then(response => response.json())
      .then(data => {
        if (data.error) {
          feedbackElement.innerHTML = translator.t("error-response");
          feedbackElement.classList.add("active"); // ✅ Добавляем "active" при ошибке
          return;
        }

        const correctAnswer = data.correctAnswer.toUpperCase();
        const isCorrect = userAnswer.toUpperCase() === correctAnswer;
        const correctAnswerInfoEl = document.querySelector('.correct-answer-info');
        if (correctAnswerInfoEl) {
          correctAnswerInfoEl.setAttribute('data-answer', data.correctAnswer);
        }
        handleQuizLogic5(isCorrect, checkAnswerButton);
      })
      .catch(error => {
        feedbackElement.innerHTML = translator.t("error-response");
        feedbackElement.classList.add("active"); // ✅ Добавляем "active" при ошибке связи
      });
  });
}


// ✅ Логика "Назад"
function handleQuizLogic5(isCorrect, button) {
  setFeedbackAndRestartButton(isCorrect, button);
  disableInputs(); // ✅ Отключаем все инпуты

  button.addEventListener("click", () => {
    clearQuizUI()

    // 🔥 Сбрасываем всё перед новым запуском
    question5Initialized = false;
    openedIndexes.clear();
    observer5.observe(document.body, { childList: true, subtree: true });
  }, { once: true });
}
